INSERT OR IGNORE INTO wyr_dilemmas (id, option_a, option_b, category, votes_a, votes_b, is_approved) VALUES
  ('wyr-deep-4', 'Live a quiet, peaceful life of 90 years with modest accomplishments', 'Live a passionate, revolutionary life of 40 years that changes history forever', 'deep', 865, 1462, 1),
  ('wyr-deep-5', 'Know when you are going to die with exact certainty', 'Know how you are going to die with exact certainty', 'deep', 722, 724, 1),
  ('wyr-deep-6', 'Have the power to save 1,000 strangers from a disaster', 'Have the power to save your one closest family member from a fatal illness', 'deep', 548, 396, 1),
  ('wyr-deep-7', 'Be completely forgotten by humanity 50 years after you die', 'Be remembered forever, but as a controversial, misunderstood figure', 'deep', 1411, 1079, 1),
  ('wyr-deep-8', 'Live in a world where everyone always speaks the complete, painful truth', 'Live in a world where polite, comforting lies keep everyone peaceful and happy', 'deep', 834, 990, 1),
  ('wyr-deep-9', 'Have the power to end world hunger forever', 'Have the power to end all wars and violent conflicts forever', 'deep', 575, 840, 1),
  ('wyr-deep-10', 'Experience extreme sorrow and pain in order to experience profound, transcendent joy', 'Live in a state of calm, stable, unshakeable contentment with no extreme highs or lows', 'deep', 578, 636, 1),
  ('wyr-deep-11', 'Be the person who breaks a painful generational cycle in your family', 'Be the person who builds generational wealth and security for your family', 'deep', 1141, 861, 1),
  ('wyr-deep-12', 'Know the ultimate purpose and meaning of the universe, but be unable to share it with anyone', 'Live with the mystery of life, but enjoy deep, fulfilling connections with other seekers', 'deep', 738, 806, 1),
  ('wyr-deep-13', 'Choose to forgive someone who deeply betrayed you and never apologized', 'Choose to cut them off completely and focus entirely on your own growth and boundaries', 'deep', 727, 960, 1),
  ('wyr-deep-14', 'Have absolute freedom with zero security or guarantees', 'Have absolute security and comfort with strict rules and limitations', 'deep', 596, 441, 1),
  ('wyr-deep-15', 'Be born 500 years in the future into an advanced, unknown civilization', 'Be born 500 years in the past into a historic culture whose destiny you already know', 'deep', 319, 387, 1),
  ('wyr-deep-16', 'Sacrifice your reputation to do the right thing when everyone believes you are wrong', 'Protect your reputation and allow a minor injustice to occur quietly without intervention', 'deep', 647, 589, 1),
  ('wyr-deep-17', 'Have the wisdom of an 80-year-old at age 20', 'Have the curiosity and wonder of a 5-year-old at age 80', 'deep', 382, 429, 1),
  ('wyr-deep-18', 'Know every secret government truth and conspiracy across history', 'Know the secret thoughts and feelings of every ancestor who came before you', 'deep', 647, 744, 1),
  ('wyr-deep-19', 'Live with the knowledge that there is life after death', 'Live with the knowledge that this mortal life is the only one you will ever have', 'deep', 631, 584, 1),
  ('wyr-deep-20', 'Be able to heal people’s emotional trauma and heartbreak with a touch', 'Be able to heal people’s physical disabilities and chronic pain with a touch', 'deep', 1419, 792, 1),
  ('wyr-deep-21', 'Lose all your memories from the past 10 years and start fresh with a clean slate', 'Keep all your memories, including heartbreaks, mistakes, and painful grief', 'deep', 743, 1186, 1),
  ('wyr-deep-22', 'Be remembered by history as a great thinker who lived in obscurity and poverty', 'Be celebrated during your lifetime as a genius but largely forgotten by future generations', 'deep', 875, 1194, 1),
  ('wyr-deep-23', 'Have everyone in the world agree on one universal moral code', 'Preserve the rich, chaotic diversity of human cultural perspectives and disagreements', 'deep', 702, 694, 1),
  ('wyr-deep-24', 'Know the exact date and location where you will meet your future spouse', 'Let the meeting be a completely unexpected, serendipitous surprise', 'deep', 549, 696, 1),
  ('wyr-deep-25', 'Have the power to speak to your future child before they are born', 'Have the power to speak to your deceased grandparent for one final hour', 'deep', 743, 1214, 1),
  ('wyr-deep-26', 'Live in a world without physical pain or suffering', 'Live in a world where pain exists, but so does courage, resilience, and compassion', 'deep', 1040, 758, 1),
  ('wyr-deep-27', 'Choose to know what your greatest lost opportunity in life was', 'Never know what could have been and focus entirely on the path ahead', 'deep', 1165, 1428, 1),
  ('wyr-deep-28', 'Be praised for accomplishments you did not earn', 'Be criticized for work you poured your heart and soul into creating', 'deep', 311, 171, 1),
  ('wyr-deep-29', 'Have the ability to look into a mirror and see who you will be in 20 years', 'Have the ability to look into a mirror and see who you were in your past life', 'deep', 947, 1232, 1),
  ('wyr-deep-30', 'Spend your life seeking personal enlightenment and inner peace', 'Spend your life fighting for social justice and helping the oppressed', 'deep', 527, 504, 1),
  ('wyr-deep-31', 'Be able to feel the collective joy and love of humanity for 1 minute', 'Be able to understand the collective wisdom and knowledge of humanity for 1 hour', 'deep', 1085, 1168, 1),
  ('wyr-deep-32', 'Choose to tell a dying loved one a comforting lie to ease their passing', 'Choose to tell them the difficult truth so they pass with complete reality', 'deep', 1019, 662, 1),
  ('wyr-deep-33', 'Live in an era of space exploration and colonization among the stars', 'Live in an era of deep ocean exploration and discovering underwater worlds', 'deep', 281, 342, 1),
  ('wyr-deep-34', 'Have unconditional self-love and self-acceptance', 'Have unconditional love and empathy for every other living human being', 'deep', 325, 551, 1),
  ('wyr-deep-35', 'Know whether humanity will survive for another 10,000 years', 'Know whether alien life exists in our galaxy right now', 'deep', 243, 192, 1),
  ('wyr-deep-36', 'Be given a second chance at one past relationship that fell apart', 'Receive a clean slate with zero baggage and meet an entirely new soulmate', 'deep', 617, 631, 1),
  ('wyr-deep-37', 'Sacrifice your personal happiness so your future children have guaranteed success', 'Prioritize your own authentic fulfillment and inspire your children by example', 'deep', 224, 260, 1),
  ('wyr-deep-38', 'Live in a world where everyone’s lifespan is strictly capped at 70 healthy years', 'Live in a world where some people live to 150 but others pass away unpredictably', 'deep', 654, 433, 1),
  ('wyr-deep-39', 'Be the architect who builds a lasting peaceful community for 1,000 families', 'Be the solitary artist whose masterpiece inspires millions across centuries', 'deep', 601, 656, 1),
  ('wyr-deep-40', 'Choose to remember everything you have ever felt, including every sorrow', 'Choose to only remember moments of love, laughter, and triumph', 'deep', 383, 564, 1),
  ('wyr-deep-41', 'Have people value you for your sharp intellect and problem-solving', 'Have people value you for your warmth, loyalty, and listening ear', 'deep', 203, 240, 1),
  ('wyr-deep-42', 'Find out that your entire life up until today was a hyper-realistic simulation', 'Find out that you are the only real conscious being in the universe and everyone else is an NPC', 'deep', 737, 415, 1),
  ('wyr-deep-43', 'Be able to take away the grief of someone who lost a child', 'Be able to give sight to someone who has been blind since birth', 'deep', 586, 507, 1),
  ('wyr-deep-44', 'Live in a society governed by pure logic with zero emotion or irrationality', 'Live in a society governed by pure emotion and art with zero cold bureaucracy', 'deep', 320, 285, 1),
  ('wyr-deep-45', 'Know the truth behind who built the pyramids and Stonehenge', 'Know the truth behind whether time travel will ever be invented by humanity', 'deep', 932, 605, 1),
  ('wyr-deep-46', 'Have the courage to speak up against injustice even when standing completely alone', 'Have the patience to build consensus and unite two opposing communities peacefully', 'deep', 354, 554, 1),
  ('wyr-deep-47', 'Choose to spend 5 years in absolute silence meditating in an ancient temple', 'Choose to spend 5 years traveling through 50 war-torn regions delivering humanitarian aid', 'deep', 172, 264, 1),
  ('wyr-deep-48', 'Be granted one wish that benefits only you', 'Be granted three wishes that can only benefit strangers in need', 'deep', 507, 459, 1),
  ('wyr-deep-49', 'Know the greatest mistake you are destined to make in the next 10 years', 'Remain unaware and trust your intuition to navigate life’s crossroads', 'deep', 537, 339, 1),
  ('wyr-deep-50', 'Be the leader who makes a difficult decision that saves 90% of your people', 'Be the philosopher who reminds people of the sanctity of the 10% who were lost', 'deep', 850, 556, 1),
  ('wyr-deep-51', 'Have your life story written as an epic, tragic novel that touches millions of souls', 'Have your life story written as a heartwarming, quiet romance with a peaceful happy ending', 'deep', 1007, 1269, 1),
  ('wyr-deep-52', 'Choose to know what your pet thinks of you and your companionship', 'Choose to know what your parents’ proudest moment of you was', 'deep', 424, 279, 1),
  ('wyr-deep-53', 'Live in an age where disease has been cured but death from aging still exists', 'Live in an age where aging has been paused but diseases are still a threat', 'deep', 525, 941, 1);

INSERT OR IGNORE INTO wyr_dilemmas (id, option_a, option_b, category, votes_a, votes_b, is_approved) VALUES
  ('wyr-deep-54', 'Be capable of feeling no anger, bitterness, or resentment ever again', 'Be capable of feeling no jealousy, envy, or comparison ever again', 'deep', 1543, 898, 1),
  ('wyr-deep-55', 'Find out that destiny is real and every choice you made was predetermined', 'Find out that the universe is purely random and you have terrifying, total free will', 'deep', 631, 700, 1),
  ('wyr-deep-56', 'Give up all your material possessions to live with pure purpose and clarity', 'Keep your wealth and possessions while continuously wrestling with existential questions', 'deep', 248, 234, 1),
  ('wyr-deep-57', 'Be the one who loves more in a relationship', 'Be the one who is loved more in a relationship', 'deep', 617, 621, 1),
  ('wyr-deep-58', 'Have the opportunity to apologize to someone you hurt who is no longer in your life', 'Have someone who hurt you reach out with a genuine, heartfelt apology', 'deep', 599, 728, 1),
  ('wyr-deep-59', 'Choose to know the deepest secret of your closest friend', 'Choose to keep your deepest secret safe from everyone forever', 'deep', 464, 813, 1),
  ('wyr-deep-60', 'Live a life where you never experience failure but achieve modest goals', 'Live a life where you fail repeatedly on a massive scale but achieve one transcendent victory', 'deep', 302, 539, 1),
  ('wyr-deep-61', 'Be remembered for discovering a fundamental law of physics', 'Be remembered for composing a symphony that brings people to tears centuries later', 'deep', 1339, 776, 1),
  ('wyr-deep-62', 'Know that your life made the world 1% better for everyone who came after you', 'Know that your life brought 100% joy and happiness to the 10 people closest to you', 'deep', 481, 706, 1),
  ('wyr-deep-63', 'Be granted the ability to understand every perspective in an argument without bias', 'Be granted the conviction and clarity to champion the most moral cause without wavering', 'deep', 234, 342, 1),
  ('wyr-deep-64', 'Choose to know whether your deceased loved ones are watching over you', 'Choose to live with faith and trust in the unseen bond of love', 'deep', 914, 1163, 1),
  ('wyr-deep-65', 'Live in a world where money does not exist and status is based on kindness', 'Live in a world where resources are so abundant that work is entirely optional', 'deep', 215, 245, 1),
  ('wyr-deep-66', 'Be the mentor who shapes the leader who changes the world', 'Be the leader who changes the world with guidance from many mentors', 'deep', 759, 1253, 1),
  ('wyr-deep-67', 'Choose to see the beauty in every mundane, everyday moment', 'Choose to experience rare, breathtaking moments of awe once every few years', 'deep', 515, 459, 1),
  ('wyr-deep-68', 'Know that you lived your life true to yourself without compromising for others', 'Know that you lived your life in service of others and eased their burdens', 'deep', 818, 1185, 1),
  ('wyr-deep-69', 'Choose to forgive yourself for your past mistakes and let go of all guilt', 'Choose to keep your self-accountability and use past guilt to fuel future goodness', 'deep', 870, 616, 1),
  ('wyr-deep-70', 'Be able to communicate with whales and dolphins and understand ocean consciousness', 'Be able to communicate with ancient trees and understand forest networks', 'deep', 1300, 1003, 1),
  ('wyr-deep-71', 'Live with the certainty that everything happens for a reason', 'Live with the freedom that you create your own reasons and meaning from chaos', 'deep', 703, 671, 1),
  ('wyr-deep-72', 'Choose to face your greatest fear right now and conquer it forever', 'Live a peaceful life by avoiding your greatest fear entirely', 'deep', 522, 363, 1),
  ('wyr-deep-73', 'Know the impact that one kind word from you had on a stranger 5 years ago', 'Know who thought of you with fondness and love today without telling you', 'deep', 240, 241, 1),
  ('wyr-deep-74', 'Be remembered as someone who was always brutally honest', 'Be remembered as someone who was always unfailingly compassionate', 'deep', 500, 470, 1),
  ('wyr-deep-75', 'Choose to experience true love for 5 brief years and then lose it', 'Choose to experience a comfortable, warm companionship for 50 peaceful years', 'deep', 804, 531, 1),
  ('wyr-deep-76', 'Have the power to remove hatred from the hearts of all world leaders', 'Have the power to remove greed from the hearts of all corporate billionaires', 'deep', 1221, 991, 1),
  ('wyr-deep-77', 'Live in a society where mental health is prioritized over economic productivity', 'Live in a society where technological advancement eliminates physical labor', 'deep', 456, 648, 1),
  ('wyr-deep-78', 'Choose to know how many times you made someone smile in your lifetime', 'Choose to know how many times someone cried tears of joy because of you', 'deep', 623, 809, 1),
  ('wyr-deep-79', 'Be remembered as a courageous rebel who stood against tyranny', 'Be remembered as a compassionate peacemaker who brought warring sides together', 'deep', 631, 547, 1),
  ('wyr-deep-80', 'Choose to let go of expectations and live completely in the present moment', 'Choose to hold ambitious visions and sacrifice present comfort for a glorious future', 'deep', 939, 1410, 1),
  ('wyr-deep-81', 'Know what happens at the end of the universe 100 billion years from now', 'Know what existed before the Big Bang at the beginning of time', 'deep', 217, 235, 1),
  ('wyr-deep-82', 'Have your heart broken once so deeply that you understand the depth of human love', 'Never have your heart broken and live with steady, gentle affection throughout life', 'deep', 551, 683, 1),
  ('wyr-deep-83', 'Choose to know the one truth about yourself that you are currently in denial about', 'Choose to let personal growth reveal your blind spots naturally over time', 'deep', 736, 724, 1),
  ('wyr-deep-84', 'Be the spark that ignites a global renaissance of art, music, and poetry', 'Be the engineer who builds the infrastructure that provides clean water to all humanity', 'deep', 854, 664, 1),
  ('wyr-deep-85', 'Choose to leave a profound legacy that outlives your name', 'Choose to live an anonymous, deeply joyful life with no concern for legacy', 'deep', 690, 696, 1),
  ('wyr-deep-86', 'Know the exact words you will say as your last sentence on Earth', 'Let your last words be an unplanned, authentic reaction to the moment', 'deep', 348, 301, 1),
  ('wyr-deep-87', 'Live with the knowledge that you were truly, deeply loved by those who matter', 'Live with the knowledge that you truly, deeply loved those who matter', 'deep', 1329, 1027, 1),
  ('wyr-deep-88', 'Choose to look back on your life from old age and say "I took the risk"', 'Choose to look back on your life from old age and say "I stayed safe and protected my family"', 'deep', 1096, 741, 1),
  ('wyr-deep-89', 'Be granted absolute clarity on every moral question you ever encounter', 'Retain the humble struggle of ethical wrestling that defines human growth', 'deep', 785, 453, 1),
  ('wyr-deep-90', 'Know that in another parallel universe, an alternate version of you achieved your wildest dream', 'Know that in this universe, you are on the exact path you were meant to walk', 'deep', 999, 692, 1),
  ('wyr-absurd-1', 'Fight 1 horse-sized duck in an arena', 'Fight 100 duck-sized horses in an arena', 'absurd', 417, 578, 1),
  ('wyr-absurd-2', 'Have Morgan Freeman narrate all your internal thoughts out loud for everyone nearby', 'Have a live 1990s sitcom laugh track play out loud whenever you make a mistake', 'absurd', 357, 323, 1),
  ('wyr-absurd-3', 'Sneeze brightly colored confetti instead of air every time you sneeze', 'Hiccup rainbow soap bubbles that float in the air whenever you get the hiccups', 'absurd', 1269, 735, 1),
  ('wyr-absurd-4', 'Only be able to whisper everything you say for the rest of your life', 'Only be able to shout everything you say at 90 decibels for the rest of your life', 'absurd', 1017, 798, 1),
  ('wyr-absurd-5', 'Have spaghetti for hair that regrows when you eat it', 'Sweat maple syrup whenever you work out at the gym', 'absurd', 777, 791, 1),
  ('wyr-absurd-6', 'Have hands the size of dinner plates', 'Have feet the size of large watermelons', 'absurd', 268, 456, 1),
  ('wyr-absurd-7', 'Have a pet dinosaur (Velociraptor) that acts like a playful puppy', 'Have a pet dragon (cat-sized) that accidentally toasts your toast in the morning', 'absurd', 869, 545, 1),
  ('wyr-absurd-8', 'Every time you enter a room, dramatic WWE wrestler entrance music blasts from the ceiling', 'Every time you exit a room, slow-motion movie explosions appear behind you', 'absurd', 723, 827, 1),
  ('wyr-absurd-9', 'Have your tastebuds on the soles of your feet', 'Have your eyes on the palms of your hands like the Pale Man in Pan’s Labyrinth', 'absurd', 1172, 1315, 1),
  ('wyr-absurd-10', 'Always have to hop on one foot whenever you cross a street', 'Always have to crawl backwards on all fours whenever you enter an elevator', 'absurd', 1010, 1227, 1),
  ('wyr-absurd-11', 'Be chased by a snail that is invincible, knows where you are, and touches you once to end you (for $10M)', 'Live a normal life with zero snail and zero $10M', 'absurd', 286, 323, 1),
  ('wyr-absurd-12', 'Have your skin turn bright neon blue whenever you get embarrassed', 'Have your hair stand straight up like an anime Super Saiyan whenever you get angry', 'absurd', 307, 174, 1),
  ('wyr-absurd-13', 'Only be able to communicate using Shakespearean Elizabethan English ("Hark! Wherefore art thou coffee?")', 'Only be able to communicate using 2010s internet meme slang ("Much wow. Very exam. So tired.")', 'absurd', 1252, 754, 1);

INSERT OR IGNORE INTO wyr_dilemmas (id, option_a, option_b, category, votes_a, votes_b, is_approved) VALUES
  ('wyr-absurd-14', 'Have every dog you walk past give you a polite nod and say "Good day, sir" in a British accent', 'Have every cat you walk past stare into your soul and whisper your middle name', 'absurd', 505, 472, 1),
