  ('wyr-absurd-22', 'Have every piece of clothing you own turn into a tuxedo or ballgown at 8 PM every night', 'Have every piece of clothing you own turn into dinosaur pajamas at 10 PM every night', 'absurd', 1206, 1135, 1),
  ('wyr-absurd-23', 'Have to high-five every stranger you make eye contact with on the street', 'Have to say "Bazinga!" at the end of every sentence you speak in public', 'absurd', 469, 867, 1),
  ('wyr-absurd-24', 'Have your sneeze sound like a roaring Tyrannosaurus Rex', 'Have your cough sound like a vintage squeaky rubber chicken', 'absurd', 429, 352, 1),
