  ('wyr-absurd-49', 'Be challenged to an intellectual chess match by an octopus who communicates via ink clouds', 'Be challenged to an arm-wrestling match by a kangaroo wearing boxing gloves', 'absurd', 275, 255, 1),
  ('wyr-absurd-50', 'Have your phone ringtone be a loud turkey gobble that cannot be silenced', 'Have your alarm clock sound like Gordon Ramsay yelling at you to wake up', 'absurd', 1436, 807, 1),
  ('wyr-absurd-51', 'Every time you take a photo, a mysterious photobombing llama appears in the background', 'Every time you record a voice memo, it sounds like you inhaled helium from a balloon', 'absurd', 330, 218, 1),
  ('wyr-absurd-52', 'Have your shoes light up like LA Lights sneakers every time you run', 'Have your socks always be mismatched with neon polka dots and stripes', 'absurd', 364, 233, 1),
  ('wyr-absurd-53', 'Have to wear a medieval knight helmet to every formal event for the rest of your life', 'Have to wear oversized fuzzy pink bunny slippers to every job interview for life', 'absurd', 1063, 1037, 1),
  ('wyr-absurd-54', 'Have your laugh sound like a cheerful dolphin clicking and chirping', 'Have your sneeze sound like an old steam locomotive train whistle', 'absurd', 232, 313, 1),
  ('wyr-absurd-55', 'Be able to slide across any hallway floor on your socks as if it were an Olympic curling rink', 'Be able to jump into piles of autumn leaves and teleport to your backyard', 'absurd', 323, 257, 1),
  ('wyr-absurd-56', 'Have your thumb turn into a functioning USB flash drive with 1 Terabyte of storage', 'Have your pinky finger turn into a functioning laser pointer that cats chase', 'absurd', 318, 380, 1),
  ('wyr-absurd-57', 'Be followed by an entourage of 3 ducks wearing tiny top hats who clap when you succeed', 'Be followed by a friendly squirrel who hands you acorns when you look stressed', 'absurd', 1397, 1123, 1),
  ('wyr-absurd-58', 'Have every door you open make the dramatic Star Trek pneumatic hiss sound', 'Have every window you close play the soft Windows XP shutdown chime', 'absurd', 1362, 1198, 1),
  ('wyr-absurd-59', 'Have to say "Eureka!" and jump in the air every time you solve a minor puzzle or bug', 'Have to dramatically bow like a stage actor every time you finish eating a meal', 'absurd', 746, 507, 1),
  ('wyr-absurd-60', 'Have your fingernails change color depending on your mood like a mood ring', 'Have your hair change color depending on the weather outside', 'absurd', 553, 718, 1),
  ('wyr-absurd-61', 'Be challenged to a dance-off by a robot street performer and you must accept', 'Be challenged to a rap battle by an elderly grandmother on the subway and you must accept', 'absurd', 946, 583, 1),
  ('wyr-absurd-62', 'Have your shadow dance the salsa whenever you are waiting in line at the DMV', 'Have your echo repeat everything you say in an overly dramatic French accent', 'absurd', 608, 940, 1),
  ('wyr-absurd-63', 'Have your car engine make race car "VROOOM" noises recorded by your own mouth', 'Have your bicycle bell sound like an opera singer hitting a high C note', 'absurd', 916, 1244, 1);

INSERT OR IGNORE INTO wyr_dilemmas (id, option_a, option_b, category, votes_a, votes_b, is_approved) VALUES
  ('wyr-absurd-64', 'Every time you drink through a straw, it makes loud comical slurp sounds', 'Every time you eat chips in a movie theater, it crunches at 100 decibels', 'absurd', 592, 473, 1),
